   <title>Image Preview</title>
   <style>
     :root {
       color-scheme: light;
       --bg: #f4f7fb;
       --surface: rgba(255, 255, 255, 0.9);
       --surface-strong: #ffffff;
       --text: #132238;
       --muted: #5c6b82;
       --border: rgba(19, 34, 56, 0.12);
       --shadow: 0 24px 60px rgba(18, 35, 63, 0.12);
       --primary: #2563eb;
       --primary-hover: #1d4ed8;
       --danger: #dc2626;
       --danger-hover: #b91c1c;
       --radius-xl: 28px;
       --radius-lg: 20px;
       --radius-md: 14px;
     }

     * {
       box-sizing: border-box;
     }

     body {
       margin: 0;
       min-height: 100vh;
       font-family: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
       color: var(--text);
       background:
         radial-gradient(circle at top left, rgba(37, 99, 235, 0.14), transparent 30%),
         radial-gradient(circle at bottom right, rgba(59, 130, 246, 0.11), transparent 35%),
         var(--bg);
       display: grid;
       place-items: center;
       padding: 32px;
     }

     .page {
       width: min(920px, 100%);
       display: grid;
       gap: 24px;
       grid-template-columns: 1.2fr 0.8fr;
       align-items: center;
     }

     .hero,
     .preview-card {
       background: var(--surface);
       backdrop-filter: blur(18px);
       border: 1px solid var(--border);
       border-radius: var(--radius-xl);
       box-shadow: var(--shadow);
     }

     .hero {
       padding: 40px;
     }

     .eyebrow {
       display: inline-flex;
       align-items: center;
       gap: 8px;
       font-size: 0.82rem;
       font-weight: 700;
       letter-spacing: 0.08em;
       text-transform: uppercase;
       color: var(--primary);
       margin-bottom: 14px;
     }

     h1 {
       margin: 0;
       font-size: clamp(2rem, 4vw, 3.5rem);
       line-height: 1.04;
       letter-spacing: -0.04em;
     }

     .lead {
       margin: 16px 0 0;
       color: var(--muted);
       font-size: 1.02rem;
       line-height: 1.7;
       max-width: 54ch;
     }

     .preview-card {
       overflow: hidden;
     }

     .image-wrap {
       aspect-ratio: 4 / 5;
       background: linear-gradient(180deg, #dbeafe 0%, #eff6ff 100%);
       position: relative;
     }

     .image-wrap img {
       width: 100%;
       height: 100%;
       object-fit: cover;
       display: block;
     }

     .image-meta {
       padding: 22px;
       display: grid;
       gap: 16px;
     }

     .image-title {
       margin: 0;
       font-size: 1.1rem;
     }

     .image-copy {
       margin: 4px 0 0;
       color: var(--muted);
       font-size: 0.95rem;
       line-height: 1.6;
     }

     .actions {
       display: flex;
       gap: 12px;
       flex-wrap: wrap;
     }

     .button {
       appearance: none;
       border: 0;
       border-radius: 999px;
       padding: 0.9rem 1.2rem;
       font: inherit;
       font-weight: 700;
       cursor: pointer;
       transition: transform 0.18s ease, background-color 0.18s ease, box-shadow 0.18s ease;
     }

     .button:hover {
       transform: translateY(-1px);
     }

     .button:focus-visible {
       outline: 3px solid rgba(37, 99, 235, 0.3);
       outline-offset: 2px;
     }

     .button-primary {
       background: var(--primary);
       color: white;
       box-shadow: 0 10px 24px rgba(37, 99, 235, 0.25);
     }

     .button-primary:hover {
       background: var(--primary-hover);
     }

     .button-danger {
       background: var(--danger);
       color: white;
     }

     .button-danger:hover {
       background: var(--danger-hover);
     }

     dialog {
       width: min(440px, calc(100% - 32px));
       border: 0;
       border-radius: 24px;
       padding: 0;
       box-shadow: 0 28px 80px rgba(15, 23, 42, 0.3);
       overflow: hidden;
       background: var(--surface-strong);
     }

     dialog::backdrop {
       background: rgba(10, 15, 25, 0.52);
       backdrop-filter: blur(6px);
     }

     .dialog-shell {
       padding: 24px;
     }

     .dialog-icon {
       width: 48px;
       height: 48px;
       border-radius: 16px;
       display: grid;
       place-items: center;
       margin-bottom: 18px;
       background: rgba(220, 38, 38, 0.1);
       color: var(--danger);
       font-size: 1.3rem;
       font-weight: 800;
     }

     .dialog-shell h2 {
       margin: 0;
       font-size: 1.4rem;
       letter-spacing: -0.03em;
     }

     .dialog-shell p {
       margin: 10px 0 0;
       color: var(--muted);
       line-height: 1.6;
     }

     .dialog-actions {
       display: flex;
       justify-content: flex-end;
       gap: 12px;
       margin-top: 24px;
     }

     @media (max-width: 760px) {
       body {
         padding: 18px;
       }

       .page {
         grid-template-columns: 1fr;
       }

       .hero {
         padding: 28px;
       }
     }
   </style>
 </head>
 <body>
   <main class="page">
     <section class="hero" aria-labelledby="page-title">
       <div class="eyebrow">Image preview</div>
       <h1 id="page-title">Review your photo before you remove it.</h1>
       <p class="lead">
         This clean preview layout keeps the image front and center while giving you a quick, confident way to confirm deletion from your library.
       </p>
     </section>

     <section class="preview-card" aria-label="Selected image">
       <div class="image-wrap">
         <img
           src="https://images.unsplash.com/photo-1517841905240-472988babdf9?auto=format&fit=crop&w=1200&q=80"
           alt="Portrait preview of a smiling dog"
         />
       </div>
       <div class="image-meta">
         <div>
           <h2 class="image-title">Golden Hour Portrait</h2>
           <p class="image-copy">Stored in your library since May 2026.</p>
         </div>
         <div class="actions">
           <button class="button button-danger trigger" type="button" aria-controls="delete-dialog">
             Delete image
           </button>
         </div>
       </div>
     </section>
   </main>

   <dialog id="delete-dialog" aria-labelledby="delete-title" aria-describedby="delete-desc">
     <div class="dialog-shell">
       <div class="dialog-icon" aria-hidden="true">!</div>
       <h2 id="delete-title">Delete this image?</h2>
       <p id="delete-desc">
         This will permanently remove the image from your library. You can’t undo this action.
       </p>
       <div class="dialog-actions">
         <button class="button" type="button" data-close>Cancel</button>
         <button class="button button-danger" type="button">Yes, delete</button>
       </div>
     </div>
   </dialog>

   <script>
     const dialog = document.getElementById("delete-dialog");
     const trigger = document.querySelector(".trigger");
     const closeButton = dialog.querySelector("[data-close]");

     trigger.addEventListener("click", () => {
       dialog.showModal();
     });

     closeButton.addEventListener("click", () => {
       dialog.close();
     });

     dialog.addEventListener("click", (event) => {
       const rect = dialog.getBoundingClientRect();
       const clickedOutside =
         event.clientX < rect.left ||
         event.clientX > rect.right ||
         event.clientY < rect.top ||
         event.clientY > rect.bottom;

       if (clickedOutside) {
         dialog.close();
       }
     });
   </script>
 </body>
